using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseNativeFaceDetail {
 public static float NormalDetailStrength=0f;
 const string Out=NurseVisualOptimization.Out;const string Folder=NurseVisualOptimization.Folder;
