 static float S(float a,float b,float x){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));}
 public static void Run(){
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  var nurse=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));nurse.GetComponent<Animator>().enabled=false;moe.GetComponent<Animator>().enabled=false;
  var target=nurse.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var reference=moe.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var mesh=NurseAnatomyRender.WorldSkin(target);var source=NurseAnatomyRender.WorldSkin(reference);var bodyTriangles=source.GetTriangles(0);source.subMeshCount=1;source.SetTriangles(bodyTriangles,0);var surface=new GameObject("Native facial normal transfer surface");var collider=surface.AddComponent<MeshCollider>();collider.sharedMesh=source;
  var sp=source.vertices;var sn=source.normals;var st=source.tangents;var su=source.uv;var si=source.triangles;var p=mesh.vertices;var nn=mesh.normals;var tt=mesh.tangents;var uv=mesh.uv;var triangles=mesh.triangles;
  var original=Read(Folder+"/Atlas_Normal.png");var pixels=original.GetPixels();var packedSource=Read(AssetDatabase.GetAssetPath(reference.sharedMaterial.GetTexture("_RMOE")));var packedAccum=new Color[512*512];var packedWeight=new float[512*512];var normalSource=Read(AssetDatabase.GetAssetPath(reference.sharedMaterial.GetTexture("_Normal")));var albedoSource=Read(AssetDatabase.GetAssetPath(reference.sharedMaterial.GetTexture("_Albedo")));var targetAlbedo=Read(Folder+"/Atlas_Albedo.png");var targetFeral=Read(Folder+"/Atlas_Albedo_Feral.png");var colors=targetAlbedo.GetPixels();var feralColors=targetFeral.GetPixels();var skinReference=JsonUtility.FromJson<NurseMoeReference.Reference>(File.ReadAllText(Out+"/moe-skin-reference.json"));const int size=2048;int hits=0,veins=0;float maxPerturbation=0;
  for(int j=0;j<triangles.Length;j+=3){int a=triangles[j],b=triangles[j+1],c=triangles[j+2];if(Mathf.Max(p[a].y,Mathf.Max(p[b].y,p[c].y))<1.50f||Mathf.Min(p[a].y,Mathf.Min(p[b].y,p[c].y))>1.705f)continue;var aa=uv[a]*size;var bb=uv[b]*size;var cc=uv[c]*size;float d=(bb.y-cc.y)*(aa.x-cc.x)+(cc.x-bb.x)*(aa.y-cc.y);if(Mathf.Abs(d)<1e-8f)continue;
   for(int y=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.y,Mathf.Min(bb.y,cc.y))));y<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(aa.y,Mathf.Max(bb.y,cc.y))));y++)for(int x=Mathf.Max(0,Mathf.FloorToInt(Mathf.Min(aa.x,Mathf.Min(bb.x,cc.x))));x<=Mathf.Min(size-1,Mathf.CeilToInt(Mathf.Max(aa.x,Mathf.Max(bb.x,cc.x))));x++){
    float u=((bb.y-cc.y)*(x+.5f-cc.x)+(cc.x-bb.x)*(y+.5f-cc.y))/d,v=((cc.y-aa.y)*(x+.5f-cc.x)+(aa.x-cc.x)*(y+.5f-cc.y))/d,w=1-u-v;if(u<0||v<0||w<0)continue;var position=p[a]*u+p[b]*v+p[c]*w;
    float amount=S(1.50f,1.53f,position.y)*(1-S(1.685f,1.705f,position.y))*(1-S(.065f,.085f,Mathf.Abs(position.x)))*S(.025f,.050f,position.z);if(position.y>1.65f)amount*=1-S(.045f,.060f,Mathf.Abs(position.x));if(amount<.01f)continue;
