    var normal=(nn[a]*u+nn[b]*v+nn[c]*w).normalized;if(normal.z<.2f)continue;float sourceX=-Mathf.Abs(position.x)*.80f,sourceY=position.y+.088f;var point=new Vector3(sourceX,sourceY,.5f);RaycastHit hit;if(!collider.Raycast(new Ray(point,Vector3.back),out hit,1f))continue;int k=hit.triangleIndex*3;int ia=si[k],ib=si[k+1],ic=si[k+2];var bary=hit.barycentricCoordinate;var coord=su[ia]*bary.x+su[ib]*bary.y+su[ic]*bary.z;
    var color=albedoSource.GetPixelBilinear(coord.x,coord.y);if(Mathf.Max(color.r,Mathf.Max(color.g,color.b))<.22f||color.r>color.g*1.45f)continue;
    var sourceN=(sn[ia]*bary.x+sn[ib]*bary.y+sn[ic]*bary.z).normalized;var sourceT=(st[ia]*bary.x+st[ib]*bary.y+st[ic]*bary.z);var tangent=new Vector3(sourceT.x,sourceT.y,sourceT.z).normalized;var bitangent=Vector3.Cross(sourceN,tangent)*Mathf.Sign(sourceT.w);var sample=normalSource.GetPixelBilinear(coord.x,coord.y);var nativeNormal=new Vector3(sample.r*2-1,sample.g*2-1,sample.b*2-1).normalized;var worldNormal=(tangent*nativeNormal.x+bitangent*nativeNormal.y+sourceN*nativeNormal.z).normalized;
    var perturbation=worldNormal-sourceN*Vector3.Dot(worldNormal,sourceN);if(position.x>0)perturbation.x=-perturbation.x;maxPerturbation=Mathf.Max(maxPerturbation,perturbation.magnitude);
    var targetT=tt[a]*u+tt[b]*v+tt[c]*w;var nt=new Vector3(targetT.x,targetT.y,targetT.z).normalized;var nb=Vector3.Cross(normal,nt)*Mathf.Sign(targetT.w);var detailed=(normal+perturbation).normalized;var detailTS=new Vector3(Vector3.Dot(detailed,nt),Vector3.Dot(detailed,nb),Vector3.Dot(detailed,normal));int index=y*size+x;var old=new Vector3(pixels[index].r*2-1,pixels[index].g*2-1,pixels[index].b*2-1).normalized;var combined=(old+new Vector3(detailTS.x,detailTS.y,0)*amount*NormalDetailStrength).normalized;pixels[index]=new Color(combined.x*.5f+.5f,combined.y*.5f+.5f,combined.z*.5f+.5f,1);
    float purple=S(1.02f,1.20f,Mathf.Min(color.r,color.b)/Mathf.Max(.01f,color.g))*amount*.45f;if(purple>.005f){var ratio=new Color(Mathf.Clamp(color.r/skinReference.albedo.r,.35f,1.25f),Mathf.Clamp(color.g/skinReference.albedo.g,.35f,1.25f),Mathf.Clamp(color.b/skinReference.albedo.b,.35f,1.25f),1);colors[index]=Color.Lerp(colors[index],colors[index]*ratio,purple);feralColors[index]=Color.Lerp(feralColors[index],feralColors[index]*ratio,purple);veins++;}int packedIndex=(y/4)*512+x/4;float packedAmount=amount*.60f/16f;packedAccum[packedIndex]+=packedSource.GetPixelBilinear(coord.x,coord.y)*packedAmount;packedWeight[packedIndex]+=packedAmount;hits++;
   }
  }
  if(hits<1000)throw new Exception("Native facial normal transfer found too little intact skin: "+hits);original.SetPixels(pixels);original.Apply();string path=Folder+"/Atlas_Normal.png";File.WriteAllBytes(path,original.EncodeToPNG());AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);targetAlbedo.SetPixels(colors);targetAlbedo.Apply();File.WriteAllBytes(Folder+"/Atlas_Albedo.png",targetAlbedo.EncodeToPNG());AssetDatabase.ImportAsset(Folder+"/Atlas_Albedo.png",ImportAssetOptions.ForceSynchronousImport);targetFeral.SetPixels(feralColors);targetFeral.Apply();File.WriteAllBytes(Folder+"/Atlas_Albedo_Feral.png",targetFeral.EncodeToPNG());AssetDatabase.ImportAsset(Folder+"/Atlas_Albedo_Feral.png",ImportAssetOptions.ForceSynchronousImport);foreach(string tier in new[]{"Normal","Feral","Special"}){string mapPath=Folder+"/Atlas_RMOE_"+tier+".png";var t=Read(mapPath);var values=t.GetPixels();for(int k=0;k<values.Length;k++)if(packedWeight[k]>0){float alpha=values[k].a;values[k]=Color.Lerp(values[k],packedAccum[k]/packedWeight[k],Mathf.Clamp01(packedWeight[k]));values[k].a=alpha;}t.SetPixels(values);t.Apply();File.WriteAllBytes(mapPath,t.EncodeToPNG());AssetDatabase.ImportAsset(mapPath,ImportAssetOptions.ForceSynchronousImport);}File.WriteAllText(Out+"/native-face-detail.txt","Native Moe BODY SUBMESH ONLY intact forehead/cheek tangent-normal perturbations reprojected to Nurse face; native wounded pixels, hair, eyes, central nose and lips excluded. Source intact side reflected to both sides. Source-to-target tangent frames converted through world space; source base face shape not copied. Normal detail strength="+NormalDetailStrength+"; Samples="+hits+" native vascular colour texels="+veins+" maximum native perturbation="+maxPerturbation+". No mesh, bones or collider edits. Final normal remains 2048; matching native roughness/metal/AO transferred into 512 RMOE with tier emission alpha preserved.\n");UnityEngine.Object.DestroyImmediate(surface);UnityEngine.Object.DestroyImmediate(source);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(nurse);UnityEngine.Object.DestroyImmediate(moe);AssetDatabase.SaveAssets();
 }
